193: impl Execution {
194:     pub fn new(logs: &mut &[String]) -> Result<Self, ClientError> {
195:         let l = &logs[0];
196:         *logs = &logs[1..];
197: 
198:         let re = Regex::new(r"^Program (.*) invoke.*$").unwrap();
199:         let c = re
200:             .captures(l)
201:             .ok_or_else(|| ClientError::LogParseError(l.to_string()))?;
202:         let program = c
203:             .get(1)
204:             .ok_or_else(|| ClientError::LogParseError(l.to_string()))?
205:             .as_str()
