217:     pub fn push(&mut self, new_program: String) {
218:         self.stack.push(new_program);
219:     }
220: 
221:     pub fn pop(&mut self) {
222:         assert!(!self.stack.is_empty());
223:         self.stack.pop().unwrap();
224:     }
